<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import DataTable from '@/components/zs/DataTable.vue';import Toolbar from '@/components/zs/Toolbar.vue';import SearchInput from '@/components/zs/SearchInput.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import ZButton from '@/components/zs/ZButton.vue';import ScoreBadge from '@/components/crm/ScoreBadge.vue';import Pagination from '@/components/zs/Pagination.vue';import {useCrmData} from '@/composables/useCrmData';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Leads','Qualified pipeline with lead intelligence and outreach actions.');const d=useCrmData(),r=useRouter(),q=ref(''),stage=ref('All stages'),owner=ref('All owners'),page=ref(1);const columns=[{key:'name',header:'Lead'},{key:'company',header:'Company'},{key:'title',header:'Job title'},{key:'email',header:'Email'},{key:'source',header:'Source'},{key:'stage',header:'Stage'},{key:'fit',header:'Fit',align:'right' as const},{key:'intent',header:'Intent',align:'right' as const},{key:'total',header:'Total score'},{key:'owner',header:'Owner'},{key:'lastActivity',header:'Last activity'},{key:'actions',header:'',align:'right' as const}];const owners=computed(()=>[...new Set((d.leads.data.value??[]).map(x=>x.owner))]);const all=computed(()=>(d.leads.data.value??[]).filter(x=>(stage.value==='All stages'||x.stage===stage.value)&&(owner.value==='All owners'||x.owner===owner.value)&&`${x.name} ${x.company}`.toLowerCase().includes(q.value.toLowerCase())));const rows=computed(()=>all.value.slice((page.value-1)*8,page.value*8));</script>
<template><AppShell><PageHeader title="Leads" :description="`${all.length} leads in the active company`"><template #actions><ZButton @click="r.push('/crm/capture')">Add or import</ZButton><ZButton variant="outline" @click="r.push('/crm/pipeline')">View pipeline</ZButton></template></PageHeader><Panel><Toolbar><SearchInput v-model="q" placeholder="Search lead or company"/><select v-model="stage" class="field max-w-40"><option>All stages</option><option v-for="x in ['New','Contacted','Qualified','Proposal','Negotiation','Won','Lost']" :key="x">{{x}}</option></select><select v-model="owner" class="field max-w-44"><option>All owners</option><option v-for="x in owners" :key="x">{{x}}</option></select></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="1500"><template #name="{row}"><button class="font-medium text-primary hover:underline" @click="r.push(`/crm/leads/${row.id}`)">{{row.name}}</button></template><template #stage="{row}"><StatusBadge :status="row.stage"/></template><template #fit="{row}"><span class="num">{{row.score.fit}}</span></template><template #intent="{row}"><span class="num">{{row.score.intent}}</span></template><template #total="{row}"><ScoreBadge :score="row.score.total"/></template><template #actions="{row}"><div class="flex justify-end gap-1"><ZButton variant="ghost" @click="r.push(`/crm/leads/${row.id}`)">View</ZButton><ZButton variant="ghost" @click="r.push({path:'/outreach/compose',query:{lead:row.id}})">Outreach</ZButton></div></template><template #footer><Pagination :page="page" :pages="Math.ceil(all.length/8)" :total="all.length" @change="page=$event"/></template></DataTable></Panel></AppShell></template>
